#!/usr/bin/env python3
"""Content ledger and opening picker.
  ledger.py sync            register/refresh all pilot pages from front matter (opening type, voice, format, opening text)
  ledger.py next FORMAT     suggest opening types for a new page of that format (least recently used, weighted, eligible)
  ledger.py report          opening type usage so far
The ledger is the system's memory: it later also holds GSC and GA4 results per page (see guidelines/40-learning-system.md)."""
import sys, os, re, json, glob, datetime
HOME = os.path.expanduser('~/carestream-content')
LEDGER = HOME + '/ledger/content-ledger.json'
LIB = HOME + '/library/openings.json'

def load(p, default):
    try: return json.load(open(p))
    except Exception: return default

def first_para(body):
    body = re.sub(r'^#\s.*$', '', body, count=1, flags=re.M)
    for p in re.split(r'\n\s*\n', body):
        p = p.strip()
        if len(p.split()) > 6 and not p.startswith(('-', '!', '#', '|', '{', '*')): return p
    return ''

def pages():
    out = []
    for f in sorted(glob.glob(HOME + '/pilot/**/*.md', recursive=True)):
        t = open(f, encoding='utf-8').read()
        m = re.match(r'^---\n(.*?)\n---\n(.*)$', t, re.S)
        if not m: continue
        fm, body = m.group(1), m.group(2)
        g = lambda k: (re.search('^' + k + r':\s*(.*)$', fm, re.M) or [None, ''])[1].strip()
        fp = first_para(re.split(r'\n#{1,3}\s*Meta title options', body)[0])
        out.append({'file': f.replace(HOME + '/', ''), 'slug': g('slug'), 'type': g('type'), 'family': g('family'), 'format': g('format') or 'collection',
                    'voice': g('voice'), 'opening_type': g('opening_type'), 'opening_text': fp,
                    'first12': ' '.join(re.findall(r"[a-z0-9']+", fp.lower())[:12]), 'last_reviewed': g('last_reviewed')})
    return out

def sync():
    led = load(LEDGER, {'entries': []})
    old = {e['slug']: e for e in led['entries']}
    for p in pages():
        e = old.get(p['slug'], {'created': str(datetime.date.today()), 'status': 'draft', 'metrics': {}, 'lessons': []})
        e.update(p); old[p['slug']] = e
    led['entries'] = list(old.values())
    json.dump(led, open(LEDGER, 'w'), indent=2, ensure_ascii=False)
    print(len(led['entries']), 'pages in ledger')

def usage():
    led = load(LEDGER, {'entries': []})
    ents = sorted(led['entries'], key=lambda e: e.get('created', ''))
    return ents

def nxt(fmt):
    lib = load(LIB, {'moves': []})
    ents = usage()
    recent = [e['opening_type'] for e in ents][-8:]
    counts = {}
    for e in ents: counts[e['opening_type']] = counts.get(e['opening_type'], 0) + 1
    cand = []
    for mv in lib['moves']:
        if mv.get('status') != 'active': continue
        if fmt not in mv['fits']: continue
        if mv['id'] in recent: continue
        score = mv.get('weight', 1.0) / (1 + counts.get(mv['id'], 0))
        cand.append((score, mv['id'], mv['name']))
    cand.sort(reverse=True)
    for s, i, n in cand[:5]: print(f'{i:28} {n}  (score {s:.2f})')
    if not cand: print('no eligible move: widen fits or retire recency')

def report():
    ents = usage(); counts = {}
    for e in ents: counts[e.get('opening_type') or '(none)'] = counts.get(e.get('opening_type') or '(none)', 0) + 1
    for k, v in sorted(counts.items(), key=lambda x: -x[1]): print(f'{v:3}  {k}')

if __name__ == '__main__':
    c = sys.argv[1] if len(sys.argv) > 1 else 'report'
    if c == 'sync': sync()
    elif c == 'next': nxt(sys.argv[2] if len(sys.argv) > 2 else 'G')
    else: report()

