#!/usr/bin/env python3
"""Pick tonight's topics. Usage: pick_topics.py blog|collection N state.json
Skips every topic already on the platform (primary keyword, or a slug that contains it), anything with an owner_conflict, and spreads
clusters and formats so a night is varied. Prints JSON."""
import sys, os, re, json
HOME = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def norm(s): return re.sub(r'[^a-z0-9 ]+', '', (s or '').lower()).strip()
kind, n, state = sys.argv[1], int(sys.argv[2]), json.load(open(sys.argv[3]))
pages = state['blogs'] + state['collections']
kws = {norm(p.get('primary_keyword')) for p in pages}
slugs = ' '.join(p['slug'] for p in pages)
def used(kw):
    k = norm(kw); return k in kws or k.replace(' ', '-') in slugs
def load(f): return json.load(open(os.path.join(HOME, 'ledger', f)))
out = []
if kind == 'blog':
    seen, rows = set(), []
    for f in ['topic-backlog.json', 'topic-backlog-cpd.json', 'topic-backlog-features.json', 'topic-backlog-audits.json']:
        for i in load(f):
            if i['id'] in seen or i.get('page_type') != 'blog' or i.get('owner_conflict') or used(i['primary_keyword']): continue
            seen.add(i['id']); rows.append(i)
    rows.sort(key=lambda i: -(i.get('priority_score') or 0))
    fam, fmt = {}, set()
    for i in rows:
        if len(out) >= n: break
        c = i.get('cluster') or ''
        if fam.get(c, 0) >= 1 and len(rows) > n * 3: continue
        if i.get('format') in fmt and len(rows) > n * 3: continue
        fam[c] = fam.get(c, 0) + 1; fmt.add(i.get('format')); out.append(i)
else:
    rows = [i for i in load('collection-queue.json')['queue'] if not used(i['primary_keyword'])]
    kinds = {'training': 0, 'policies': 0}
    for i in sorted(rows, key=lambda i: -i['volume']):
        if len(out) >= n: break
        if kinds[i['kind']] >= (n + 1) // 2: continue
        kinds[i['kind']] += 1; out.append(i)
    for i in sorted(rows, key=lambda i: -i['volume']):
        if len(out) >= n: break
        if i not in out: out.append(i)
print(json.dumps(out, indent=1, ensure_ascii=False))

